TypeScript sample:

// consumer.ts
import { LazyFragmentReader, ToolClient } from '@redwood/sdk';
async function streamHandler(stream) {
  const reader = new LazyFragmentReader(stream, { validate: true });
  for await (const partial of reader.readValidatedObjects()) {
    if (partial.type === 'tool_call') {
      const response = await ToolClient.invoke(partial.tool, partial.args);
      await reader.emitToolResponse(partial.call_id, response);
    } else {
      console.log('partial structured emission', partial.payload);
    }
  }
}

Go sample:

// consumer.go
package main
import (
  "context"
  "fmt"
  "github.com/redwood/sdk-go"
)
func streamHandler(ctx context.Context, stream sdk.Stream) error {
  reader := sdk.NewLazyFragmentReader(stream, sdk.ReaderOptions{Validate:true})
  ch := reader.ReadValidated()
  for msg := range ch {
    switch msg.Type {
    case sdk.MessageTypeToolCall:
      resp, _ := sdk.InvokeTool(ctx, msg.ToolName, msg.Args)
      reader.EmitToolResponse(msg.CallID, resp)
    default:
      fmt.Println("partial payload", msg.Payload)
    }
  }
  return nil
}
